import{_ as d,o as r,c as e,a0 as n}from"./chunks/framework.B7o6dWmz.js";const c=JSON.parse('{"title":"对比 new-api / one-api","description":"","frontmatter":{"aside":false},"headers":[],"relativePath":"zh-Hans/compare.md","filePath":"zh-Hans/compare.md","lastUpdated":1793979958000}'),o={name:"zh-Hans/compare.md"};function a(s,t,i,g,p,h){return r(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="对比-new-api-one-api" tabindex="-1">对比 new-api / one-api <a class="header-anchor" href="#对比-new-api-one-api" aria-label="Permalink to &quot;对比 new-api / one-api&quot;">​</a></h1><p>NetonAPI 不是在 one-api / new-api 上改出来的分支，而是从<strong>运营平台</strong>的角度重新设计：定价以官方价为锚、每条渠道核算真实成本、 亏本的价格保存不了、每一笔扣费都能按「单价 × tokens」逐笔对上。下表对照的是两个最主流的开源中转站项目。</p><table tabindex="0"><thead><tr><th>能力</th><th>NetonAPI 1.0</th><th><a href="https://github.com/QuantumNous/new-api" target="_blank" rel="noreferrer">new-api</a></th><th><a href="https://github.com/songquanpeng/one-api" target="_blank" rel="noreferrer">one-api</a></th></tr></thead><tbody><tr><td><strong>定价方式</strong></td><td>以官方价为锚：售价 = 官方价 × 加价率；分组、单个用户都可按模型谈「官方价 N 折」</td><td>倍率体系：模型倍率 × 补全倍率 × 分组倍率；按次固定价；分档表达式定价</td><td>倍率体系：分组倍率 × 模型倍率 × 补全倍率</td></tr><tr><td><strong>按用户 × 模型的协议价</strong></td><td>有（「协议定价」页：搜用户、逐模型打折、可批量）</td><td>按用户分组倍率区分</td><td>按用户分组倍率区分</td></tr><tr><td><strong>渠道真实成本</strong></td><td>每条渠道记录拿货价（官方价折扣 / 拉取上游价目接口 / 按模型手填），异常变动挂起待确认</td><td>公开文档未涉及</td><td>公开文档未涉及</td></tr><tr><td><strong>毛利保护</strong></td><td>售价低于渠道成本的定价<strong>保存不了</strong>；定价体检列出每个「分组 × 渠道」的最差毛利；利润看板</td><td>公开文档未涉及</td><td>公开文档未涉及</td></tr><tr><td><strong>官方价维护</strong></td><td>定时从价源同步官方价，涨跌先挂起由运营确认，完整调价记录</td><td>倍率设置，可同步上游倍率</td><td>内置默认倍率，手动调整</td></tr><tr><td><strong>扣费与展示</strong></td><td>扣费 = tokens × 用户看到的单价（逐项取整），控制台、价格表、账单三处一致；缓存价缺失时按输入价计，不白送缓存命中</td><td>预扣后按实际用量多退少补</td><td>预扣后按实际用量结算</td></tr><tr><td><strong>账务</strong></td><td>预留 → 结算两阶段，进程崩溃可恢复，异常进入人工复核队列；每笔请求冻结定价快照</td><td>预扣 + 后结算</td><td>预扣 + 后结算</td></tr><tr><td><strong>计费分组</strong></td><td>由 API Key 决定：运营可直接指定到某把 Key（专线 / 特价）</td><td>用户分组，令牌可选分组</td><td>用户分组、渠道分组</td></tr><tr><td><strong>API Key 安全</strong></td><td>只在创建时显示一次，库里只存哈希；渠道上游 Key 加密存储</td><td>列表中可查看、复制</td><td>列表中可查看、复制</td></tr><tr><td><strong>接入协议</strong></td><td>OpenAI（Chat、Responses）、Anthropic、Gemini 原生入口，<strong>任意方向互转</strong>（工具调用、图片、thinking、缓存用量保真）</td><td>OpenAI Chat、Responses、Anthropic、Gemini 四种文本协议互转；另有 Realtime WebSocket</td><td>统一为 OpenAI 格式</td></tr><tr><td><strong>上游类型</strong></td><td>OpenAI 兼容站、Azure OpenAI、Anthropic、Gemini、AWS Bedrock、Vertex AI</td><td>数十种，含国内外厂商</td><td>30 余家国内外厂商</td></tr><tr><td><strong>渠道容错</strong></td><td>优先级 + 权重；失败自动换渠道；上游说「没有这个模型」时换渠道而不是报错给用户；Key 自动停用与冷却；定时测速</td><td>优先级 + 权重、重试、渠道亲和、多 Key</td><td>负载均衡、失败重试、按成功率自动禁用</td></tr><tr><td><strong>任务类接口</strong>（Midjourney、视频等）</td><td>暂不支持</td><td>支持（JS 插件扩展）</td><td>不支持</td></tr><tr><td><strong>运营权限</strong></td><td>菜单与按钮级权限，预置网关运营 / 财务 / 客服 / 只读四个角色</td><td>细粒度权限</td><td>管理员 / 超级管理员</td></tr><tr><td><strong>用户登录</strong></td><td>账号密码、手机验证码（需配短信）、邮箱找回密码</td><td>OAuth / OIDC、Passkey、两步验证</td><td>邮箱、GitHub、飞书、微信公众号</td></tr><tr><td><strong>充值</strong></td><td>管理员手动充值、兑换码、在线支付（支付宝、四方支付，可扩展）；支付密钥只写不读</td><td>兑换码、易支付、Stripe、订阅</td><td>兑换码、充值链接</td></tr><tr><td><strong>实现与部署</strong></td><td>Kotlin/Native <strong>单个原生可执行文件</strong>，运行期无 JVM；PostgreSQL（Redis 可选）</td><td>Go 单二进制 / Docker；SQLite / MySQL / PostgreSQL</td><td>Go 单二进制 / Docker；SQLite / MySQL</td></tr><tr><td><strong>项目状态</strong></td><td>1.0.0 正式版</td><td>持续发布（v1.0.0-rc 系列）</td><td>最新版本 v0.6.10（2025-02），此后无新版本</td></tr></tbody></table><p>new-api、one-api 两列依据各自公开的 README 与文档整理（2026-11），「公开文档未涉及」表示没有找到相关说明，不代表一定没有；细节以对方最新版本为准。</p><h2 id="什么时候选哪个" tabindex="-1">什么时候选哪个 <a class="header-anchor" href="#什么时候选哪个" aria-label="Permalink to &quot;什么时候选哪个&quot;">​</a></h2><ul><li><strong>你要运营一个中转站、关心每一单赚不赚钱、要给大客户谈价</strong>：选 NetonAPI。</li><li><strong>你需要 Midjourney、视频生成等任务类接口，或者要接非常多的小众厂商</strong>：new-api 目前覆盖更广。</li><li><strong>你只要一个轻量的统一转发、不太在意成本核算</strong>：one-api 足够简单。</li></ul><p>想先看 NetonAPI 跑起来的样子，去 <a href="https://neton.cloud" target="_blank" rel="noreferrer">Neton Cloud</a> 注册试用。</p>',7)])])}const u=d(o,[["render",a]]);export{c as __pageData,u as default};
